INSERT INTO feature VALUES('open-judgement','sessions','Openness at a world crossing','located-judgements','implemented','uncommon','mainstream languages','A crossing asks two judgements of its type: mobile, authority, and open, representation — the value names no location, so its bytes read the same at every world, in this process or another (migrate-wire). They agree on data and part at a handle `A at w`, mobile always and open exactly when `A` is; a migration''s result or a constant read at another world is refused `NotOpen` when what a handle holds is not open and `Immobile` when a former met directly is not mobile, the report spelling the failing former.','core-checker surface-corpus surface-diagnostics','corpus/model/worlds/open.gandr corpus/pathological/worlds/open.gandr corpus/pathological/worlds/immobile-crossing.gandr','corpus/model/worlds/open.gandr',NULL);
